//! Persistent topological names, v0 (`docs/research/tecnologia-rust-cad.md` §6).
//!
//! A face is referenced by how it was born, not by a kernel index:
//! `F1:+Z` is the +Z face of the box created by feature F1, `F3:g2` the third
//! face generated by F3, `F1:+Z/1` the second piece of `F1:+Z` after a split.
//! The engine propagates names through every operation's `OpHistory`; Phase 1
//! adds semantic queries and scored fallback on top of this.

use crate::FeatureId;
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use std::fmt;
use std::str::FromStr;

/// Name of a face that survives rebuilds.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum TopoName {
    /// A face of a primitive, by role (e.g. `+Z` for a box's top face).
    Primitive {
        /// Feature that created the primitive.
        feature: FeatureId,
        /// Role inside the primitive: `+X -X +Y -Y +Z -Z` for boxes.
        role: String,
    },
    /// A face an operation created that has no single parent, numbered by a
    /// deterministic geometric order.
    Generated {
        /// The feature that created it.
        feature: FeatureId,
        /// Ordinal among the faces that feature generated.
        ordinal: u32,
    },
    /// A piece of a face that was split.
    Split {
        /// The face that was split.
        parent: Box<TopoName>,
        /// Ordinal among the pieces.
        ordinal: u32,
    },
}

/// Error parsing a [`TopoName`].
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[error("invalid face name `{0}` (expected e.g. `F1:+Z`, `F3:g2`, `F1:+Z/1`)")]
pub struct NameParseError(pub String);

impl fmt::Display for TopoName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TopoName::Primitive { feature, role } => write!(f, "{feature}:{role}"),
            TopoName::Generated { feature, ordinal } => write!(f, "{feature}:g{ordinal}"),
            TopoName::Split { parent, ordinal } => write!(f, "{parent}/{ordinal}"),
        }
    }
}

/// Longest accepted name, to bound parsing work on hostile input.
const MAX_NAME_LEN: usize = 256;

impl FromStr for TopoName {
    type Err = NameParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let err = || NameParseError(s.chars().take(64).collect());
        if s.len() > MAX_NAME_LEN {
            return Err(err());
        }
        if let Some((parent, ord)) = s.rsplit_once('/') {
            let ordinal = ord.parse().map_err(|_| err())?;
            return Ok(TopoName::Split {
                parent: Box::new(parent.parse()?),
                ordinal,
            });
        }
        let (feature, role) = s.split_once(':').ok_or_else(err)?;
        let feature: FeatureId = feature.parse().map_err(|_| err())?;
        if let Some(Ok(ordinal)) = role.strip_prefix('g').map(str::parse) {
            return Ok(TopoName::Generated { feature, ordinal });
        }
        let valid_role = !role.is_empty()
            && role
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '_' | '.'));
        if !valid_role {
            return Err(err());
        }
        Ok(TopoName::Primitive {
            feature,
            role: role.to_owned(),
        })
    }
}

impl Serialize for TopoName {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.collect_str(self)
    }
}

impl<'de> Deserialize<'de> for TopoName {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = String::deserialize(d)?;
        s.parse().map_err(serde::de::Error::custom)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn round_trips() {
        for s in ["F1:+Z", "F12:-X", "F3:g0", "F3:g12", "F1:+Z/1", "F2:g1/0/3"] {
            let n: TopoName = s.parse().unwrap();
            assert_eq!(n.to_string(), s);
            let json = serde_json::to_string(&n).unwrap();
            assert_eq!(serde_json::from_str::<TopoName>(&json).unwrap(), n);
        }
    }

    #[test]
    fn rejects_garbage() {
        for s in [
            "", "F1", ":+Z", "X1:+Z", "F1:", "F1:+Z/x", "F1:a b", "F-1:+Z",
        ] {
            assert!(s.parse::<TopoName>().is_err(), "{s}");
        }
    }

    proptest! {
        #[test]
        fn never_panics(s in ".{0,300}") {
            let _ = s.parse::<TopoName>();
        }
    }
}
